/* contest2026_090_CiRCLE/board/contest_board/src/board_bringup.c */

#include <nuttx/config.h>
#include <debug.h>
#include <syslog.h>
#include <nuttx/fs/fs.h>

#ifdef CONFIG_WATCHDOG
#  include "espressif/esp_wdt.h"
#endif

#ifdef CONFIG_DEV_GPIO
#  include "espressif/esp_gpio.h"
#endif

#ifdef CONFIG_ESPRESSIF_SPIFLASH
#  include "esp_board_spiflash.h"
#endif

#ifdef CONFIG_I2C_DRIVER
#  include "esp_board_i2c.h"
#endif

#include "board.h"

/****************************************************************************
 * Name: esp_bringup
 *
 * Description:
 *   Initialize board-specific peripherals.
 ****************************************************************************/

int esp_bringup(void)
{
  int ret = OK;

#ifdef CONFIG_FS_PROCFS
  ret = nx_mount(NULL, "/proc", "procfs", 0, NULL);
  if (ret < 0)
    {
      _err("Failed to mount procfs at /proc: %d\n", ret);
    }
#endif

#ifdef CONFIG_ESPRESSIF_MWDT0
  ret = esp_wdt_initialize("/dev/watchdog0", ESP_WDT_MWDT0);
  if (ret < 0)
    {
      _err("Failed to initialize WDT: %d\n", ret);
    }
#endif

#ifdef CONFIG_DEV_GPIO
  ret = esp_gpio_init();
  if (ret < 0)
    {
      _err("Failed to initialize GPIO: %d\n", ret);
    }
#endif

#ifdef CONFIG_ESPRESSIF_SPIFLASH
  ret = board_spiflash_init();
  if (ret < 0)
    {
      _err("Failed to initialize SPI Flash: %d\n", ret);
    }
#endif

#ifdef CONFIG_I2C_DRIVER
  ret = board_i2c_init();
  if (ret < 0)
    {
      _err("Failed to initialize I2C: %d\n", ret);
    }
#endif

  return ret;
}

